import logging
from typing import Optional, Tuple, Dict, Any
from pydantic import BaseModel, Field

from backend.app.agents.base import BaseAgent
from backend.app.models.schemas import (
    MarketAnalystOutput,
    ProductManagerOutput,
    TechArchitectOutput,
    PitchWriterOutput
)

logger = logging.getLogger(__name__)


class SingleAgentDeliverables(BaseModel):
    """Complete multi-deliverable venture pack generated by a single prompt."""
    market: MarketAnalystOutput = Field(..., description="Market analysis deliverable")
    prd: ProductManagerOutput = Field(..., description="Product requirements document deliverable")
    architecture: TechArchitectOutput = Field(..., description="Technical architecture deliverable")
    pitch: PitchWriterOutput = Field(..., description="10-slide investor pitch deck deliverable")


class SingleAgent(BaseAgent):
    """Solo Founder / Single Agent Baseline (Step 1 / Ablation Study).
    
    Generates all four startup deliverables (Market, PRD, Architecture, Pitch)
    using a single unified prompt to establish a rigorous ablation baseline
    against multi-agent debate pipelines.
    """

    def __init__(
        self,
        model: Optional[str] = None,
        provider: Optional[str] = None,
        **kwargs
    ):
        super().__init__(
            name="Single Agent Baseline",
            prompt_file="single_agent.md",
            model=model,
            provider=provider,
            **kwargs
        )

    async def run(self, idea: str) -> Tuple[SingleAgentDeliverables, Dict[str, Any]]:
        """Synthesize the complete venture pack for the startup idea in a single run."""
        user_content = (
            f"Please independently formulate and structure the complete startup venture package "
            f"for the following startup idea:\n\n"
            f"Idea: {idea}\n\n"
            f"Generate all four core artifacts: market analysis (with TAM/SAM/SOM and competitors), "
            f"product requirements (PRD with user personas and stories), "
            f"technical architecture (with Mermaid diagram and monthly cost breakdown), "
            f"and 10-slide investor pitch deck."
        )

        deliverables, meta = await self.execute_structured(
            user_content=user_content,
            schema=SingleAgentDeliverables,
            temperature=0.2
        )

        return deliverables, meta
